-- Save MJ: Queries (core SP call only)
DECLARE @Name_3f1b1b35 NVARCHAR(255),
@CategoryID_3f1b1b35 UNIQUEIDENTIFIER,
@UserQuestion_3f1b1b35 NVARCHAR(MAX),
@Description_3f1b1b35 NVARCHAR(MAX),
@SQL_3f1b1b35 NVARCHAR(MAX),
@TechnicalDescription_3f1b1b35 NVARCHAR(MAX),
@OriginalSQL_3f1b1b35 NVARCHAR(MAX),
@Feedback_3f1b1b35 NVARCHAR(MAX),
@Status_3f1b1b35 NVARCHAR(15),
@QualityRank_3f1b1b35 INT,
@ExecutionCostRank_3f1b1b35 INT,
@UsesTemplate_3f1b1b35 BIT,
@AuditQueryRuns_3f1b1b35 BIT,
@CacheEnabled_3f1b1b35 BIT,
@CacheTTLMinutes_3f1b1b35 INT,
@CacheMaxSize_3f1b1b35 INT,
@EmbeddingVector_3f1b1b35 NVARCHAR(MAX),
@EmbeddingModelID_3f1b1b35 UNIQUEIDENTIFIER,
@CacheValidationSQL_3f1b1b35 NVARCHAR(MAX),
@SQLDialectID_3f1b1b35 UNIQUEIDENTIFIER,
@Reusable_3f1b1b35 BIT,
@ExternalDataSourceID_3f1b1b35 UNIQUEIDENTIFIER,
@ID_3f1b1b35 UNIQUEIDENTIFIER
SET
  @Name_3f1b1b35 = N'GetConversationsForMemoryManager'
SET
  @CategoryID_3f1b1b35 = '5609FBC7-381C-4F9C-9C74-04B52C1FF3DA'
SET
  @UserQuestion_3f1b1b35 = N'What conversations have new activity that need to be analyzed for memory extraction?'
SET
  @Description_3f1b1b35 = N'Returns all conversation data needed for memory extraction in a single query: conversations with new activity, their details with ratings, and linked agent runs for scope inheritance. Optimized to replace 4 separate sequential queries.'
SET
  @SQL_3f1b1b35 = N'-- Get Conversations for Memory Manager - Single optimized query
-- Returns all data needed for memory extraction: conversations, details, ratings, and agent runs
-- Uses JSON aggregation to include related data without row multiplication
-- This replaces 4 separate queries with 1 query for better performance
--
-- Parameters:
--   @since (optional): ISO date string - only include conversations with new activity after this date
--   @agentIds: Array of agent IDs that have memory enabled (rendered via sqlIn filter)

SELECT
    c.ID as ConversationID,
    c.UserID,

    -- Most recent agent run ID for this conversation (for scope inheritance)
    (
        SELECT TOP 1 ar.ID
        FROM [${flyway:defaultSchema}].[vwAIAgentRuns] ar
        WHERE ar.ConversationID = c.ID
        AND ar.AgentID IN {{ agentIds | sqlIn }}
        ORDER BY ar.StartedAt DESC
    ) as AgentRunID,

    -- Conversation details as JSON array with ratings included
    (
        SELECT
            cd.ID as id,
            cd.Role as role,
            cd.Message as message,
            cd.__mj_CreatedAt as createdAt,
            cdr.Rating as rating,
            cdr.Comments as ratingComment
        FROM [${flyway:defaultSchema}].[vwConversationDetails] cd
        LEFT OUTER JOIN [${flyway:defaultSchema}].[vwConversationDetailRatings] cdr
            ON cdr.ConversationDetailID = cd.ID
        WHERE cd.ConversationID = c.ID
        AND cd.Status = ''Complete''
        ORDER BY cd.__mj_CreatedAt ASC
        FOR JSON PATH
    ) as MessagesJSON,

    -- Rating summary flags
    CASE WHEN EXISTS (
        SELECT 1 FROM [${flyway:defaultSchema}].[vwConversationDetails] cd
        INNER JOIN [${flyway:defaultSchema}].[vwConversationDetailRatings] cdr ON cdr.ConversationDetailID = cd.ID
        WHERE cd.ConversationID = c.ID AND cdr.Rating >= 8
    ) THEN 1 ELSE 0
END as HasPositiveRating,

    CASE WHEN EXISTS (
        SELECT 1 FROM [${flyway:defaultSchema}].[vwConversationDetails] cd
        INNER JOIN [${flyway:defaultSchema}].[vwConversationDetailRatings] cdr ON cdr.ConversationDetailID = cd.ID
        WHERE cd.ConversationID = c.ID AND cdr.Rating <= 3
    ) THEN 1 ELSE 0
END as HasNegativeRating,

    CASE WHEN NOT EXISTS (
        SELECT 1 FROM [${flyway:defaultSchema}].[vwConversationDetails] cd
        INNER JOIN [${flyway:defaultSchema}].[vwConversationDetailRatings] cdr ON cdr.ConversationDetailID = cd.ID
        WHERE cd.ConversationID = c.ID
    ) THEN 1 ELSE 0
END as IsUnrated

FROM [${flyway:defaultSchema}].[vwConversations] c

-- Only include conversations with new activity since last run
WHERE EXISTS (
    SELECT 1 FROM [${flyway:defaultSchema}].[vwConversationDetails] cd_new
    WHERE cd_new.ConversationID = c.ID
    {% if since %}
    AND cd_new.__mj_CreatedAt >= {{ since | sqlDate }}
    {% endif %}
)

-- Only include conversations linked to agents that have memory enabled
AND EXISTS (
    SELECT 1 FROM [${flyway:defaultSchema}].[vwAIAgentRuns] ar
    WHERE ar.ConversationID = c.ID
    AND ar.AgentID IN {{ agentIds | sqlIn }}
)

ORDER BY c.__mj_UpdatedAt DESC
'
SET
  @TechnicalDescription_3f1b1b35 = N'Single-query optimization that replaces 4 separate RunView calls in Memory Manager (get conversations, get agent runs, get details, get ratings). Uses SQL Server FOR JSON PATH to aggregate conversation details with ratings as JSON arrays. Returns rating summary flags (HasPositiveRating, HasNegativeRating, IsUnrated) and most recent AgentRunID for scope inheritance. Reduces database round trips from 4 to 1.'
SET
  @Status_3f1b1b35 = N'Approved'
